/*
 * AlertDialog.
 *
 * Severity is NOT red/amber/green. Destructive reads as the DEEP END OF
 * THE ACCENT RAMP — the same language Banner's `danger` tone already speaks —
 * so a reseeded device stays coherent instead of sprouting a hue the seed
 * never defined. On the default seed that lands as a deep purple; on a sky
 * seed it is a deep blue. It is still unmistakably the heavy answer,
 * because weight and depth carry the message, not hue.
 *
 * Composes var(--echo-*) only.
 */

.echo-alert__backdrop {
  position: fixed;
  /* Modal's scale. The site chrome's sticky rail is at 40. */
  z-index: var(--echo-z-overlay, 200);
  inset: 0;
  background: color-mix(in oklab, var(--echo-seam) 88%, black);
  opacity: 0.66;
  transition: opacity var(--echo-duration-swap) ease;
}

.echo-alert__backdrop[data-starting-style],
.echo-alert__backdrop[data-ending-style] {
  opacity: 0;
}

.echo-alert__popup {
  position: fixed;
  top: 50%;
  left: 50%;
  z-index: var(--echo-z-modal, 210);
  box-sizing: border-box;
  width: min(27rem, calc(100vw - 2.5rem));
  padding: var(--echo-space-10);
  border-radius: var(--echo-radius-2xl);
  transform: translate(-50%, -50%);
  background: linear-gradient(158deg, var(--echo-cap) 0%, var(--echo-surface) 44%);
  color: var(--echo-text);
  outline: none;
  box-shadow: var(
    --echo-shadow-modal,
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 46%, transparent),
    inset 0 0 0 1px var(--echo-seam),
    0 40px 80px -24px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.85 * var(--echo-shade, 1) * 100%), transparent),
    0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent),
    0 calc(6px * var(--echo-drawn, 0)) 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
  transition:
    opacity var(--echo-duration-glide) ease,
    transform var(--echo-duration-glide) cubic-bezier(0.16, 1, 0.3, 1);
}

.echo-alert__popup[data-starting-style],
.echo-alert__popup[data-ending-style] {
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.96);
}
/* With motion running (usePopupMotion), GSAP draws the arrival and exit:
   the CSS fade stands down so the two never fight. */
.echo-alert__popup[data-motion],
.echo-alert__popup[data-motion][data-starting-style],
.echo-alert__popup[data-motion][data-ending-style] {
  opacity: 1;
  transform: translate(-50%, -50%);
  transition: none;
}

/*
 * A destructive dialog carries a lit rail at its top edge — one lit thing,
 * at the top of the panel, in the ramp's emissive stop.
 */
.echo-alert__popup[data-destructive]::before {
  content: "";
  position: absolute;
  top: 0;
  inset-inline-start: 26px;
  inset-inline-end: 26px;
  height: 2px;
  border-radius: 0 0 var(--echo-radius-xs) var(--echo-radius-xs);
  background: var(--echo-accent-3);
  box-shadow: 0 0 10px color-mix(in oklch, var(--echo-accent-glow) 70%, transparent);
}

.echo-alert__title {
  margin: 0 0 var(--echo-space-3);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-tight, -0.01em);
  color: var(--echo-text);
}

.echo-alert__desc {
  margin: 0;
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}

.echo-alert__body {
  margin-top: var(--echo-space-7);
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}

.echo-alert__actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--echo-space-5);
  margin-top: var(--echo-space-10);
}

/* --- the two answers ----------------------------------------------------- */

.echo-alert__cancel,
.echo-alert__confirm,
.echo-alert__trigger {
  height: calc(38px * var(--echo-density, 1));
  padding: 0 var(--echo-space-8);
  border: 0;
  border-radius: var(--echo-radius-lg);
  cursor: pointer;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-semibold, 600);
}

/* Cancel is the plain cap — the safe answer is the ordinary one. */
.echo-alert__cancel,
.echo-alert__trigger {
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 62%);
  color: var(--echo-text);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 60%, transparent),
    0 calc(2px - 1.5px * var(--press, 0)) 0 var(--echo-cap-shadow);
}

.echo-alert__confirm {
  background: var(--echo-cap);
  color: var(--echo-text);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 60%, transparent),
    0 calc(2px - 1.5px * var(--press, 0)) 0 var(--echo-cap-shadow);
}

/*
 * The destructive answer: deep ramp stops for the cap, the palest stop for the
 * legend. The theme holds that pairing to AA on every accent, and the theme
 * tests check it ("alert-dialog/destructive confirm"), so it survives a reseed.
 */
.echo-alert__confirm[data-destructive] {
  background: linear-gradient(180deg, var(--echo-accent-5) 0%, var(--echo-accent-6) 100%);
  color: var(--echo-accent-1);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.2 * var(--echo-gloss, 1))),
    0 calc(2px - 1.5px * var(--press, 0)) 0 var(--echo-accent-7),
    0 6px 16px color-mix(in oklch, var(--echo-accent-glow) 30%, transparent);
}

/* The press is usePressable's: the cap travels onto its seam, which shortens
   under it (--press). No :active jump here — it would fight the stroke. */

.echo-alert__cancel:focus-visible,
.echo-alert__confirm:focus-visible,
.echo-alert__trigger:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

@media (prefers-reduced-motion: reduce) {
  .echo-alert__popup {
    transition-duration: var(--echo-duration-glitch);
  }
  .echo-alert__popup[data-starting-style],
  .echo-alert__popup[data-ending-style] {
    transform: translate(-50%, -50%);
  }
}

"use client";

/**
 * AlertDialog.
 *
 * Modal already covers the STRUCTURE. What is different here is everything a
 * user cannot see in a screenshot:
 *
 *  - `role="alertdialog"` and a required description, so a screen reader is
 *    told this is a decision, not a panel.
 *  - No dismissal by backdrop click or Escape leading to the destructive path:
 *    Base UI's AlertDialog refuses outside-press by construction. You have to
 *    answer it. That is the entire reason it is not a Modal with red buttons.
 *  - Its own sound. `caution` on open — a sawtooth, the only rough waveform in
 *    the token set — because a destructive confirm should not arrive with the
 *    same friendly chime as a settings panel. Confirming plays `error` when the
 *    action is destructive, and nothing at all when it is not.
 *
 *   <AlertDialog
 *     trigger={<HardwareButton>Erase</HardwareButton>}
 *     title="Erase all takes?"
 *     description="This cannot be undone."
 *     confirmLabel="Erase"
 *     onConfirm={erase}
 *   />
 *
 * Deliberately NOT a compound API, unlike Menu and Sheet. A confirm has one
 * shape — question, consequence, two answers — and every part a consumer could
 * rearrange is a way to build one that is missing its consequence or has two
 * confirm buttons. The props are the guardrail.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import * as React from "react";
import { isValidElement, type ReactElement, type ReactNode } from "react";
import { AlertDialog as BaseAlertDialog } from "@base-ui/react/alert-dialog";
import type { EchoDismissEvent, EchoPortalContainer } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { liquidBloom, usePopupMotion } from "echo-ui-core/presence";
import { usePressable } from "echo-ui-core/tactile";
import "./alert-dialog.css";

export interface AlertDialogProps {
  /** Element or text that opens the dialog. */
  trigger?: ReactNode;
  /** The decision, as a question. */
  title: ReactNode;
  /**
   * What happens if they say yes. Required: a confirm without its consequence
   * is a dialog that has already decided for the user.
   */
  description: ReactNode;
  /** Extra detail between the description and the answers. */
  children?: ReactNode;
  /** Label for the confirming answer. Name the ACTION ("Erase"), never "OK". */
  confirmLabel?: string;
  cancelLabel?: string;
  /**
   * Whether confirming destroys something. Default true — this component only
   * exists for the destructive case, and defaulting to false would make the
   * dangerous spelling the quiet one.
   */
  destructive?: boolean;
  onConfirm?: () => void;
  onCancel?: () => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean, eventDetails: EchoDismissEvent) => void;
  /**
   * Where the dialog mounts. Defaults to <body>. Pass an element inside a
   * scoped theme (`createEchoTheme(seed, { selector })`) and the dialog wears
   * that theme too — mounted on <body>, it can only read the :root one.
   */
  container?: EchoPortalContainer;
}

/**
 * The element to render as the trigger, or null to wrap `trigger` in a plain
 * button. In development, an element passed from a server component can arrive
 * as a lazy reference, which `isValidElement` rejects, so it got wrapped in a
 * second button (BUG-14). `use` unwraps it, as Radix's Slot does. React 18 has
 * neither `use` nor server components, so it never meets one. The key is built
 * at runtime so bundlers don't warn about a missing export on React 18.
 */
function useTriggerElement(trigger: ReactNode): ReactElement | null {
  if (isValidElement(trigger)) return trigger;
  const use = (React as unknown as Record<string, unknown>)[" use ".trim()];
  if (
    typeof use === "function" &&
    typeof trigger === "object" &&
    trigger !== null &&
    (trigger as { $$typeof?: symbol }).$$typeof === Symbol.for("react.lazy")
  ) {
    const payload = (trigger as { _payload?: unknown })._payload;
    if (payload && typeof (payload as PromiseLike<unknown>).then === "function") {
      const resolved: unknown = use(payload);
      if (isValidElement(resolved)) return resolved;
    }
  }
  return null;
}

export function AlertDialog({
  trigger,
  title,
  description,
  children,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  destructive = true,
  onConfirm,
  onCancel,
  open,
  defaultOpen,
  onOpenChange,
  container,
}: AlertDialogProps) {
  const triggerElement = useTriggerElement(trigger);
  const sound = useSoundOptional();
  // Liquid bloom, the same arrival as Modal: out of a pill in the middle.
  const bloom = usePopupMotion(liquidBloom);
  // The answers and the plain trigger are molded caps: they press like the
  // library's keys, down onto their 2px seam.
  const triggerPress = usePressable<HTMLButtonElement>({}, { travel: 1.5, tilt: 3 });
  const cancelPress = usePressable<HTMLButtonElement>({}, { travel: 1.5, tilt: 3 });
  const confirmPress = usePressable<HTMLButtonElement>({}, { travel: 1.5, tilt: 3 });

  return (
    <BaseAlertDialog.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={(next, eventDetails) => {
        // The rough waveform, once, on arrival. Not on every re-render.
        if (next) sound?.play("caution");
        onOpenChange?.(next, eventDetails);
      }}
    >
      {trigger != null &&
        (triggerElement ? (
          <BaseAlertDialog.Trigger render={triggerElement} />
        ) : (
          <BaseAlertDialog.Trigger className="echo-alert__trigger" {...triggerPress}>
            {trigger}
          </BaseAlertDialog.Trigger>
        ))}

      <BaseAlertDialog.Portal container={container}>
        <BaseAlertDialog.Backdrop className="echo-alert__backdrop" />
        <BaseAlertDialog.Popup ref={bloom} className="echo-alert__popup" data-destructive={destructive || undefined}>
          <BaseAlertDialog.Title className="echo-alert__title">{title}</BaseAlertDialog.Title>
          <BaseAlertDialog.Description className="echo-alert__desc">
            {description}
          </BaseAlertDialog.Description>
          {children != null ? <div className="echo-alert__body">{children}</div> : null}

          <div className="echo-alert__actions">
            {/*
              Cancel comes FIRST in the DOM, so it is what Tab reaches first and
              what a keyboard user confirms by reflex. The destructive answer
              should never be one blind Enter away.
            */}
            <BaseAlertDialog.Close className="echo-alert__cancel" onClick={() => onCancel?.()} {...cancelPress}>
              {cancelLabel}
            </BaseAlertDialog.Close>
            <BaseAlertDialog.Close
              className="echo-alert__confirm"
              data-destructive={destructive || undefined}
              {...confirmPress}
              onClick={() => {
                if (destructive) sound?.play("error");
                onConfirm?.();
              }}
            >
              {confirmLabel}
            </BaseAlertDialog.Close>
          </div>
        </BaseAlertDialog.Popup>
      </BaseAlertDialog.Portal>
    </BaseAlertDialog.Root>
  );
}
